#[derive(Clone)]
struct ParserComment {
    literal: ffi::WireString,
    location: ffi::WireSourceLocation,
}

struct ParserState {
    tokens: Vec<ffi::WireLocatedToken>,
    comments: Vec<ParserComment>,
    cursor: usize,
    source: ffi::WireString,
    current_error: String,
    current_node_id: i64,
    experimental_solidity_enabled: bool,
    evm_version: EvmVersion,
    current_compiler_version: String,
    inside_modifier: bool,
    reported_errors: Vec<ffi::WireParserError>,
    reported_warnings: Vec<ffi::WireParserError>,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum EvmVersion {
    Homestead,
    TangerineWhistle,
    SpuriousDragon,
    Byzantium,
    Constantinople,
    Petersburg,
    Istanbul,
    Berlin,
    London,
    Paris,
    Shanghai,
    Cancun,
    Prague,
    Osaka,
    Future,
}

impl EvmVersion {
    fn current() -> Self {
        Self::Osaka
    }

    fn from_name(name: &str) -> Option<Self> {
        match name {
            "homestead" => Some(Self::Homestead),
            "tangerineWhistle" => Some(Self::TangerineWhistle),
            "spuriousDragon" => Some(Self::SpuriousDragon),
            "byzantium" => Some(Self::Byzantium),
            "constantinople" => Some(Self::Constantinople),
            "petersburg" => Some(Self::Petersburg),
            "istanbul" => Some(Self::Istanbul),
            "berlin" => Some(Self::Berlin),
            "london" => Some(Self::London),
            "paris" => Some(Self::Paris),
            "shanghai" => Some(Self::Shanghai),
            "cancun" => Some(Self::Cancun),
            "prague" => Some(Self::Prague),
            "osaka" => Some(Self::Osaka),
            "@future" => Some(Self::Future),
            _ => None,
        }
    }
}

impl Default for ParserState {
    fn default() -> Self {
        Self {
            tokens: Vec::new(),
            comments: Vec::new(),
            cursor: 0,
            source: empty_string(),
            current_error: "Invalid token.".to_string(),
            current_node_id: 0,
            experimental_solidity_enabled: false,
            evm_version: EvmVersion::current(),
            current_compiler_version: String::new(),
            inside_modifier: false,
            reported_errors: Vec::new(),
            reported_warnings: Vec::new(),
        }
    }
}

impl ParserState {
    fn ensure_token_index(&mut self, _index: usize) {}

    fn ensure_current_token(&mut self) {}

    fn advance_cursor(&mut self) -> u64 {
        if self.cursor < self.tokens.len() {
            self.cursor += 1;
            1
        } else {
            0
        }
    }
}

struct ActiveParserStateGuard {
    previous: *mut ParserState,
}

impl ActiveParserStateGuard {
    fn new(state: &mut ParserState) -> Self {
        ACTIVE_PARSER_STATE.with(|active| {
            let previous = active.replace(state as *mut ParserState);
            Self { previous }
        })
    }
}

impl Drop for ActiveParserStateGuard {
    fn drop(&mut self) {
        ACTIVE_PARSER_STATE.with(|active| active.set(self.previous));
    }
}

fn take_stored_parser_state() -> ParserState {
    PARSER_STATE.with(|state| std::mem::take(&mut *state.borrow_mut()))
}

fn parser_state<R>(f: impl FnOnce(&ParserState) -> R) -> R {
    ACTIVE_PARSER_STATE.with(|active| {
        let state = active.get();
        if state.is_null() {
            PARSER_STATE.with(|stored| f(&stored.borrow()))
        } else {
            // Top-level parsing installs a scoped active state. The guard owns exclusive
            // access for the parse duration, so helpers can read it without RefCell traffic.
            unsafe { f(&*state) }
        }
    })
}

fn parser_state_mut<R>(f: impl FnOnce(&mut ParserState) -> R) -> R {
    ACTIVE_PARSER_STATE.with(|active| {
        let state = active.get();
        if state.is_null() {
            PARSER_STATE.with(|stored| f(&mut stored.borrow_mut()))
        } else {
            // See parser_state: the active parse scope guarantees unique mutable access.
            unsafe { f(&mut *state) }
        }
    })
}

